'use strict';

// Browser entry point. Reads the wire-format from the encrypted-post wrapper,
// drives the UI via `ui.js`, derives & decrypts via `crypto.js`, and persists
// the derived key (when autoSave is on) via `storage.js`.

const ui = require('./ui');
const cryptoMod = require('./crypto');
const dom = require('./dom');
const storage = require('./storage');

const SUPPORTED_FORMAT = '4';

function readWireFormat(mainElement) {
  const ds = mainElement.dataset;
  const ciphertextNode = mainElement.querySelector('script#hbeData');
  const wire = {
    format: ds.hbeFormat,
    wpm: ds.wpm || 'Wrong password.',
    whm: ds.whm || ds.wpm || 'Wrong password.',
    saltHex: ds.salt,
    nonceHex: ds.nonce,
    iterations: parseInt(ds.kdfIterations, 10) || 250000,
    autoSave: ds.autoSave === 'true',
    ciphertextHex: ciphertextNode ? ciphertextNode.textContent.trim() : '',
    // Multi-level fields (undefined when not present — single-password mode):
    levels: null,
    minLevel: 0,
    integrityHashes: null,
    pageCorruptMessage: 'Content integrity check failed. The data may have been tampered with.',
    levelPassMessage: ds.wpm || 'Wrong password.',
  };

  // Parse multi-level data attributes if present.
  if (ds.hbeLevels) {
    try {
      wire.levels = JSON.parse(ds.hbeLevels);
    } catch (_e) {
      wire.levels = null;
    }
  }
  if (ds.minLevel) {
    const ml = parseInt(ds.minLevel, 10);
    if (Number.isInteger(ml)) wire.minLevel = ml;
  }
  if (ds.hbeIntegrity) {
    try {
      wire.integrityHashes = JSON.parse(ds.hbeIntegrity);
    } catch (_e) {
      wire.integrityHashes = null;
    }
  }
  if (ds.pageCorruptMessage) {
    wire.pageCorruptMessage = ds.pageCorruptMessage;
  }
  if (ds.levelPassMessage) {
    wire.levelPassMessage = ds.levelPassMessage;
  }

  // Read per-level ciphertext blocks.
  if (wire.levels && wire.levels.length > 0) {
    wire.levelCiphertexts = {};
    const scripts = mainElement.querySelectorAll('script[type="application/x-hbe-cipher"]');
    for (const s of scripts) {
      const lvl = parseInt(s.dataset.level, 10);
      if (Number.isInteger(lvl)) {
        wire.levelCiphertexts[lvl] = s.textContent.trim();
      }
    }
  }

  return wire;
}

function dispatchDecryptEvent(mode) {
  // Fire on `window` for v3 back-compat — both READMEs document
  // `window.addEventListener('hexo-blog-decrypt', fn)` as the public API.
  // Old listeners that only access `e.type` continue to work; new listeners
  // can additionally read `e.detail.mode` ('manual' | 'cached').
  try {
    window.dispatchEvent(new CustomEvent('hexo-blog-decrypt', { detail: { mode } }));
  } catch (_e) {
    // CustomEvent constructor unavailable on very old browsers — fall back
    // to plain Event (no detail).
    try {
      window.dispatchEvent(new Event('hexo-blog-decrypt'));
    } catch (_e2) { /* ignore — no event API at all */ }
  }
}

function pageKey() {
  // Per-URL bucket so different encrypted posts don't collide in localStorage.
  return location.pathname + location.search;
}

// ── Integrity check (multi-level defence-in-depth) ──────────────────
// Runs before any decryption. Computes SHA-256(ciphertext||salt||nonce||pwdcheck)
// for the currently selected level and compares with the server-computed
// integrity hash stored in data-hbe-integrity. A mismatch means the deployment
// artifact was tampered with after build — lock down immediately.
async function runIntegrityCheck(wire) {
  if (!wire.levels || !wire.integrityHashes) return true; // single-password mode, skip
  for (const lvl of wire.levels) {
    const expectedHash = wire.integrityHashes[lvl.level];
    if (!expectedHash) continue;
    try {
      const saltBytes = cryptoMod.hexToBytes(lvl.salt);
      const nonceBytes = cryptoMod.hexToBytes(lvl.nonce);
      const ctHex = wire.levelCiphertexts && wire.levelCiphertexts[lvl.level];
      if (!ctHex) continue;
      const ctBytes = cryptoMod.hexToBytes(ctHex);
      const actualHash = await cryptoMod.computeIntegrityHash(ctBytes, saltBytes, nonceBytes, lvl.pwdcheck);
      if (actualHash !== expectedHash) {
        return false;
      }
    } catch (_e) {
      return false;
    }
  }
  return true;
}

// ── Lock-down: hide form, show corrupt message ─────────────────────
function lockDownPage(mainElement, message) {
  const form = mainElement.querySelector('#hbeForm');
  if (form) form.style.display = 'none';
  const select = mainElement.querySelector('#hbeLevelSelect');
  if (select && select.parentNode) select.parentNode.style.display = 'none';
  // Show the error in the alert region, styled prominently.
  let alert = mainElement.querySelector('[role="alert"]');
  if (!alert) {
    alert = document.createElement('div');
    alert.setAttribute('role', 'alert');
    alert.className = 'hbe hbe-error hbe-corrupt';
    mainElement.querySelector('.hbe-content').appendChild(alert);
  }
  alert.textContent = message;
}

// ── Multi-level handleSubmit ───────────────────────────────────────
async function handleMultiLevelSubmit(mainElement, wire, form, guardedReveal) {
  ui.clearError(mainElement);
  ui.setBusy(form, true);

  const password = ui.readPassword(form);
  if (!password) {
    ui.setBusy(form, false);
    ui.showError(mainElement, wire.levelPassMessage);
    return;
  }

  const selectedLevel = ui.getSelectedLevel();
  if (selectedLevel === null || !wire.levels) {
    ui.setBusy(form, false);
    ui.showError(mainElement, wire.levelPassMessage);
    return;
  }

  // Find the level metadata.
  const levelInfo = wire.levels.find(function (l) { return l.level === selectedLevel; });
  if (!levelInfo) {
    ui.setBusy(form, false);
    ui.showError(mainElement, wire.levelPassMessage);
    return;
  }

  const ctHex = wire.levelCiphertexts && wire.levelCiphertexts[selectedLevel];
  if (!ctHex) {
    ui.setBusy(form, false);
    ui.showError(mainElement, wire.levelPassMessage);
    return;
  }

  // Pre-verification: HMAC pwdcheck before expensive PBKDF2.
  let pwdcheckOk = false;
  try {
    const saltBytes = cryptoMod.hexToBytes(levelInfo.salt);
    const candidatePwdcheck = await cryptoMod.computePwdCheck(password, saltBytes);
    pwdcheckOk = candidatePwdcheck === levelInfo.pwdcheck;
  } catch (_e) {
    pwdcheckOk = false;
  }

  if (!pwdcheckOk) {
    ui.setBusy(form, false);
    ui.showError(mainElement, wire.levelPassMessage);
    return;
  }

  // PBKDF2 + AES-GCM decrypt.
  let result;
  try {
    result = await cryptoMod.tryDecryptWithPassword({
      password: password,
      saltHex: levelInfo.salt,
      nonceHex: levelInfo.nonce,
      ciphertextHex: ctHex,
      iterations: wire.iterations,
    });
  } finally {
    ui.setBusy(form, false);
  }

  if (!result.ok) {
    // GCM auth tag failed — pwdcheck passed but decrypt failed.
    // This is the "data corrupted" path (shouldn't happen if integrity
    // check passed, but we handle it as a safety net).
    lockDownPage(mainElement, wire.pageCorruptMessage);
    return;
  }

  // Save to sessionStorage for cross-navigation auto-decrypt.
  try {
    await storage.sessionSave({
      pageKey: pageKey(),
      key: result.key,
      saltHex: levelInfo.salt,
      level: selectedLevel,
    });
  } catch (_e) { /* best-effort */ }

  if (wire.autoSave) {
    await storage.save({
      pageKey: pageKey(),
      key: result.key,
      saltHex: levelInfo.salt,
      nonceHex: levelInfo.nonce,
      autoSave: true,
    });
  }

  await guardedReveal(result.plaintext, 'manual');
}

async function reveal(mainElement, plaintext, mode) {
  dom.swapInDecryptedDOM(mainElement, plaintext);
  dispatchDecryptEvent(mode);
}

async function tryAutoDecrypt(mainElement, wire, guardedReveal) {
  // ── Multi-level: check sessionStorage first ──────────────────────
  if (wire.levels && wire.levels.length > 0) {
    // Try sessionStorage for each level (find the first cached key
    // whose level is still >= min_level and salt matches).
    for (const lvl of wire.levels) {
      if (lvl.level < wire.minLevel) continue;
      const cached = await storage.sessionLoad({
        pageKey: pageKey(),
        expectedSaltHex: lvl.salt,
      });
      if (!cached || cached.level !== lvl.level) continue;
      const ctHex = wire.levelCiphertexts && wire.levelCiphertexts[lvl.level];
      if (!ctHex) continue;
      const result = await cryptoMod.tryDecryptWithKey({
        key: cached.key,
        nonceHex: lvl.nonce,
        ciphertextHex: ctHex,
      });
      if (!result.ok) {
        storage.sessionClear(pageKey());
        continue;
      }
      // Pre-select this level in the dropdown.
      const select = document.getElementById('hbeLevelSelect');
      if (select) select.value = String(lvl.level);
      await guardedReveal(result.plaintext, 'cached');
      return true;
    }
  }

  // ── Single-password: existing localStorage autoSave ──────────────
  if (!wire.autoSave) return false;
  const cachedKey = await storage.load({
    pageKey: pageKey(),
    expectedSaltHex: wire.saltHex,
  });
  if (!cachedKey) return false;
  const result = await cryptoMod.tryDecryptWithKey({
    key: cachedKey,
    nonceHex: wire.nonceHex,
    ciphertextHex: wire.ciphertextHex,
  });
  if (!result.ok) {
    storage.clear(pageKey());
    return false;
  }
  await guardedReveal(result.plaintext, 'cached');
  return true;
}

async function handleSubmit(mainElement, wire, form, guardedReveal) {
  // Multi-level path: delegate to the multi-level handler.
  if (wire.levels && wire.levels.length > 0) {
    return handleMultiLevelSubmit(mainElement, wire, form, guardedReveal);
  }

  // Single-password path (existing behaviour).
  ui.clearError(mainElement);
  ui.setBusy(form, true);
  const password = ui.readPassword(form);
  if (!password) {
    ui.setBusy(form, false);
    ui.showError(mainElement, wire.wpm);
    return;
  }
  let result;
  try {
    result = await cryptoMod.tryDecryptWithPassword({
      password,
      saltHex: wire.saltHex,
      nonceHex: wire.nonceHex,
      ciphertextHex: wire.ciphertextHex,
      iterations: wire.iterations,
    });
  } finally {
    ui.setBusy(form, false);
  }
  if (!result.ok) {
    ui.showError(mainElement, wire.wpm);
    return;
  }
  if (wire.autoSave) {
    await storage.save({
      pageKey: pageKey(),
      key: result.key,
      saltHex: wire.saltHex,
      nonceHex: wire.nonceHex,
      autoSave: true,
    });
  }
  await guardedReveal(result.plaintext, 'manual');
}

async function bootstrap() {
  const mainElement = document.getElementById('hexo-blog-encrypt');
  if (!mainElement) return;
  const wire = readWireFormat(mainElement);

  if (wire.format !== SUPPORTED_FORMAT) {
    ui.showError(
      mainElement,
      'hexo-blog-encrypt: this page was built with an incompatible plugin version. ' +
      'Rebuild the site after upgrading the plugin.'
    );
    return;
  }

  // ── Integrity check (multi-level defence-in-depth) ───────────────
  // Runs before any user interaction. If the deployment artifact was
  // tampered with, lock down immediately — hide form, show corrupt msg.
  // The integrity check is SRI-protected: the <script> tag loading this
  // bundle has integrity="sha384-...", so an attacker cannot modify this
  // check to skip it.
  const integrityOk = await runIntegrityCheck(wire);
  if (!integrityOk) {
    lockDownPage(mainElement, wire.pageCorruptMessage);
    return;
  }

  // ── Render level select (multi-level mode) ──────────────────────
  if (wire.levels && wire.levels.length > 0) {
    ui.renderLevelSelect(wire.levels, wire.minLevel);
  }

  // Single-shot reveal guard: with autoSave/sessionStorage on,
  // `tryAutoDecrypt` runs in parallel with the form submit handler.
  // If the user types fast enough to submit BEFORE auto-decrypt
  // resolves, both paths can call `reveal` on the same `mainElement` —
  // the second `replaceChild` would throw because the wrapper is
  // already detached. The guard makes whoever wins the race the sole
  // DOM-mutator.
  let revealed = false;
  var guardedReveal = async function (plaintext, mode) {
    if (revealed) return;
    revealed = true;
    await reveal(mainElement, plaintext, mode);
  };

  // ── htmx history cache cleanup (T5) ────────────────────────────
  // Before htmx saves a DOM snapshot to its history cache, check if
  // the current page is decrypted. If so, swap the decrypted DOM back
  // to the original encrypted shell so plaintext never leaks into
  // htmx's localStorage cache.
  if (typeof window.htmx !== 'undefined') {
    var originalShellHTML = mainElement.outerHTML;
    window.addEventListener('htmx:beforeHistorySave', function () {
      var el = document.getElementById('hexo-blog-encrypt');
      if (el && el.classList.contains('hbe-decrypted-content')) {
        // Replace the decrypted content with the original shell.
        // htmx will cache this instead of the plaintext.
        var temp = document.createElement('div');
        temp.innerHTML = originalShellHTML;
        var shell = temp.firstChild;
        el.parentNode.replaceChild(shell, el);
      }
    });
  }

  var form = mainElement.querySelector('#hbeForm');
  ui.attachSubmit(form, function () { return handleSubmit(mainElement, wire, form, guardedReveal); });

  var auto = await tryAutoDecrypt(mainElement, wire, guardedReveal);
  if (!auto && !revealed) {
    var input = mainElement.querySelector('#hbePass');
    if (input) input.focus();
  }
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', bootstrap);
} else {
  bootstrap();
}
