'use strict';

// Per-post localStorage entry storing the derived AES key + the salt/nonce that
// produced the corresponding ciphertext. On reload we re-import the key and
// attempt decryption silently; the user is never re-prompted.
//
// Schema (v4):
//   {
//     version: 4,
//     dk:      base64(rawKeyBytes),  // 32 bytes
//     salt:    <hex64>,              // matches data-salt
//     nonce:   <hex24>,              // retained for v4 schema compatibility
//   }
//
// IMPORTANT: when `autoSave` is false, save() is a no-op. When reading, any
// entry with a non-4 version (or v3 leftovers like `hmk`/`hmacDigest`) is
// purged + ignored.

const STORAGE_KEY_PREFIX = 'hbe.v4.';
const SCHEMA_VERSION = 4;

function storageKey(pageKey) {
  return STORAGE_KEY_PREFIX + pageKey;
}

function bytesToBase64(bytes) {
  let bin = '';
  for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
  return btoa(bin);
}

function base64ToBytes(b64) {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

async function save({ pageKey, key, saltHex, nonceHex, autoSave }) {
  if (!autoSave) return;
  try {
    const raw = await crypto.subtle.exportKey('raw', key);
    const entry = {
      version: SCHEMA_VERSION,
      dk: bytesToBase64(new Uint8Array(raw)),
      salt: saltHex,
      nonce: nonceHex,
    };
    localStorage.setItem(storageKey(pageKey), JSON.stringify(entry));
  } catch (_e) {
    // localStorage.setItem can throw QuotaExceededError or SecurityError
    // (private mode, disabled storage). Silently ignore — autoSave is
    // best-effort UX.
  }
}

async function load({ pageKey, expectedSaltHex }) {
  let entry;
  try {
    const raw = localStorage.getItem(storageKey(pageKey));
    if (!raw) return null;
    entry = JSON.parse(raw);
  } catch (_e) {
    return null;
  }

  // Purge stale or v3 entries.
  if (
    !entry
    || entry.version !== SCHEMA_VERSION
    || typeof entry.dk !== 'string'
    || typeof entry.salt !== 'string'
    || typeof entry.nonce !== 'string'
    || 'hmk' in entry
    || 'hmacDigest' in entry
  ) {
    try { localStorage.removeItem(storageKey(pageKey)); } catch (_e) { /* ignore */ }
    return null;
  }

  // If the encrypted page's salt changed, the cached key is stale. Nonce is
  // not part of PBKDF2 key derivation; decrypt still uses the current page's
  // nonce and ciphertext, and failure clears the cache in main.js.
  if (entry.salt !== expectedSaltHex) {
    try { localStorage.removeItem(storageKey(pageKey)); } catch (_e) { /* ignore */ }
    return null;
  }

  try {
    const rawBytes = base64ToBytes(entry.dk);
    const key = await crypto.subtle.importKey(
      'raw',
      rawBytes,
      { name: 'AES-GCM' },
      true,
      ['decrypt']
    );
    return key;
  } catch (_e) {
    try { localStorage.removeItem(storageKey(pageKey)); } catch (_e2) { /* ignore */ }
    return null;
  }
}

function clear(pageKey) {
  try { localStorage.removeItem(storageKey(pageKey)); } catch (_e) { /* ignore */ }
}

// ── sessionStorage module (coexists with localStorage autoSave) ──
// sessionStorage provides same-tab cross-navigation auto-decrypt.
// localStorage (above) provides cross-session "remember me".
// On page load we check sessionStorage first (fast, no re-prompt),
// then fall back to localStorage autoSave, then show the password form.

const SESSION_KEY_PREFIX = 'hbe.session.';

function sessionKey(pageKey) {
  return SESSION_KEY_PREFIX + pageKey;
}

/**
 * Save derived key to sessionStorage after successful manual decrypt.
 * Value shape: { level, dk: base64(rawKey), salt: hex64 }
 */
async function sessionSave({ pageKey, key, saltHex, level }) {
  try {
    const raw = await crypto.subtle.exportKey('raw', key);
    const entry = {
      level: level,
      dk: bytesToBase64(new Uint8Array(raw)),
      salt: saltHex,
    };
    sessionStorage.setItem(sessionKey(pageKey), JSON.stringify(entry));
  } catch (_e) {
    // sessionStorage can throw SecurityError (sandboxed iframe, etc.).
    // Silently ignore — best-effort UX.
  }
}

/**
 * Load derived key from sessionStorage.
 * Returns { key, level } or null.
 */
async function sessionLoad({ pageKey, expectedSaltHex }) {
  let entry;
  try {
    const raw = sessionStorage.getItem(sessionKey(pageKey));
    if (!raw) return null;
    entry = JSON.parse(raw);
  } catch (_e) {
    return null;
  }

  if (
    !entry
    || typeof entry.dk !== 'string'
    || typeof entry.salt !== 'string'
    || typeof entry.level !== 'number'
  ) {
    try { sessionStorage.removeItem(sessionKey(pageKey)); } catch (_e) { /* ignore */ }
    return null;
  }

  // Salt mismatch → stale entry (different build of the same URL).
  // Also skip if the cached level is now below min_level.
  // (min_level check is done by the caller after parsing wire format.)
  if (entry.salt !== expectedSaltHex) {
    try { sessionStorage.removeItem(sessionKey(pageKey)); } catch (_e) { /* ignore */ }
    return null;
  }

  try {
    const rawBytes = base64ToBytes(entry.dk);
    const key = await crypto.subtle.importKey(
      'raw',
      rawBytes,
      { name: 'AES-GCM' },
      true,
      ['decrypt']
    );
    return { key, level: entry.level };
  } catch (_e) {
    try { sessionStorage.removeItem(sessionKey(pageKey)); } catch (_e2) { /* ignore */ }
    return null;
  }
}

function sessionClear(pageKey) {
  try { sessionStorage.removeItem(sessionKey(pageKey)); } catch (_e) { /* ignore */ }
}

module.exports = {
  save,
  load,
  clear,
  STORAGE_KEY_PREFIX,
  SCHEMA_VERSION,
  sessionSave,
  sessionLoad,
  sessionClear,
};
